tools.example:
function y = smallHelper(x) %#codegen
coder.inline("always");
y = 2*x + 1;
end

function y = entry(x) %#codegen
y = coder.inlineCall(filterStage(x)) + coder.nonInlineCall(bigStage(x));
end

function y = sinLUT(idx) %#codegen
tbl = coder.const(sin(linspace(0, 2*pi, 256)));
y = tbl(idx);
end

function y = dot4(a, b) %#codegen
y = 0;
for k = coder.unroll(1:4)
    y = y + a(k)*b(k);
end
end

function y = squares(n) %#codegen
y = coder.nullcopy(zeros(1, n));
for k = 1:n
    y(k) = k^2;
end
end

function y = logValue(x) %#codegen
if coder.target("MATLAB")
    fprintf("x = %g\n", x);    % only in MATLAB
else
    coder.ceval("printf", "x = %f\n", x);
end
y = x;
end

function y = firApply(x) %#codegen
S = coder.load("coeffs.mat", "b");
y = filter(S.b, 1, x);
end

function y = callScale(x) %#codegen
y = zeros(size(x));
coder.cinclude("scale.h");
coder.ceval("scaleArray", coder.rref(x), coder.wref(y), int32(numel(x)));
end

coder.cinclude("<time.h>");
t = coder.opaque("time_t");
t = coder.ceval("time", []);

function writeLog(msg) %#codegen
f = coder.opaque("FILE *", "NULL", "HeaderFile", "<stdio.h>");
f = coder.ceval("fopen", ["log.txt" 0], ["a" 0]);
coder.ceval("fputs", [msg 0], f);
coder.ceval("fclose", f);
end

