function y = useLib(x) %#codegen
coder.updateBuildInfo("addSourceFiles", "scale.c", fullfile(pwd, "csrc"));
coder.updateBuildInfo("addIncludePaths", fullfile(pwd, "csrc"));
coder.cinclude("scale.h");
y = 0; y = coder.ceval("scale", x);
end

