function dout = ramWrap(din, addr, we) %#codegen
persistent ram
if isempty(ram)
    ram = hdl.RAM(RAMType="Single port");
end
dout = ram(din, addr, we);
end

function y = macPipe(a, b, c) %#codegen
prod = coder.hdl.pipeline(a*b, 2);
y = prod + c;
end

function y = sum8(x) %#codegen
y = fi(0, 1, 20, 8);
coder.hdl.loopspec("unroll");
for k = 1:8
    y(:) = y + x(k);
end
end

